        <tr style="background-color: rgba(10, 191, 182, 0.05);">
          <td style="padding: 10px; color: var(--accent); font-weight: bold;"> (5-Star / Honorary)</td>
          <td style="padding: 10px; color: var(--text-primary); font-weight: 500;">Field Marshal</td>
          <td style="padding: 10px; color: var(--text-primary); font-weight: 500;">Admiral of the Fleet</td>
          <td style="padding: 10px; color: var(--text-primary); font-weight: 500;">Marshal of the IAF</td>
        </tr>
